      priv->jpeg_error = true;
      priv->jpeg_ring_read = write_pos;


      if (priv->capture_cb != NULL)
        {
          bk7258_camera_now(&ts);
          priv->capture_cb(EIO, 0, &ts, priv->capture_cb_arg);
        }

